head.script:
scwin.t_setNodeSet_dataList2_onclick = function() {
    treeview1.setNodeSet("data:dataList2", {
        label: "gong_nm",
        value: "gong_code",
        depth: "gong_depth",
        checkbox: "gover_type"
    });
}
scwin.t_setNodeSet_dataList1_onclick = function() {
    treeview1.setNodeSet("data:dataList1", {
        label: "gong_nm",
        value: "gong_code",
        depth: "gong_depth",
        checkbox: "gover_type"
    });
}
scwin.treeview1_ondrop = function(dragNode, dropNode, dragControl, dropControl, e) {
    this.moveNode(dragNode.index, dropNode.index, confirm("자식노드로넣기"));
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 오른쪽의 setNodeSet('data:dataList2',obj)버튼을 클릭한다.
    //1. Run the sample file and click the setNodeSet ("data: dataList2", obj) button on the right.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('t_setNodeSet_dataList2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. TreeView체크값이 설정된 dataList2에 따라 동적으로 변경된다.
    //1. The TreeView check value is changed dynamically according to the set dataList2.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview1_label_1').innerText == '_다사 문화복지센터 건립'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그다음 setNodeSet("data:dataList1",obj) 버튼을 클릭한다.
    //2. Then click the setNodeSet ("data: dataList1", obj) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('t_setNodeSet_dataList1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. TreeView체크값이 설정된 dataList1에 따라 동적으로 변경된다.
    //2. The TreeView check value is dynamically changed according to the set dataList1.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview1_label_1').innerText == '_다사 문화복지센터 건립공사'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
